  (uuid_generate_v4(), 'navajo-handmade-sterling-silver-beaded-earrings-southwestern-artisan-jewelry', '1420802555', 'https://www.etsy.com/listing/1420802555/navajo-silver-beaded-earrings-native?click_key=bf4a0812-0b60-4295-a583-07ea0206968e%3ALT38b9a5499809605343bba4d4d70d762195d46d42&click_sum=14cbfe3e&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-487527-16-41&sr_prefetch=1&pf_from=search&sts=1&content_source=bf4a0812-0b60-4295-a583-07ea0206968e%253ALT38b9a5499809605343bba4d4d70d762195d46d42',
