  (uuid_generate_v4(), 'sterling-silver-lariat-necklace-with-navajo-style-pearls-long-boho-jewelry', '1673609084', 'https://www.etsy.com/listing/1673609084/sterling-silver-lariat-necklace-with?click_key=1cfeb984-505e-4dfb-bcde-81f75e423585%3ALT0c8f76c3fc45a1213aface90bc593029c68d7c0b&click_sum=975e57bb&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-23164-11-48&sr_prefetch=1&pf_from=search&sts=1&content_source=1cfeb984-505e-4dfb-bcde-81f75e423585%253ALT0c8f76c3fc45a1213aface90bc593029c68d7c0b',
