  (uuid_generate_v4(), 'sterling-silver-navajo-style-pearl-stack-bracelet-oxidized-southwestern-navajo-s', '4605321738', 'https://www.etsy.com/listing/4605321738/sterling-silver-desert-pearl-stack?click_key=EugkcJZevM2EO6fM0v0nl1VJ0U96%3ALTe0638c944cb5ff66d6741c98131915659007cf87&click_sum=f6ae30f7&ls=a&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-784233-11-3&sr_prefetch=1&pf_from=search&cns=1&sts=1',
