  (uuid_generate_v4(), 'sterling-silver-chain-necklace-navajo-jewelry-chain-necklace', '874151543', 'https://www.etsy.com/listing/874151543/sterling-silver-chain-necklace-navajo?click_key=EuBx0mClPiSdZ1De4o4rPsxL_G69%3ALTc0f2fd3f1c7477efe06c0335015c0d364ff102bd&click_sum=44a9dda4&ls=a&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-69489-9-7&sr_prefetch=1&pf_from=search&frs=1',
